const tabId = 118779795;

const productCards = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('[data-automation-id="product-card"], li[class*="productCard"], li[class*="gallery"]'));

  // If specific card containers aren't cleanly tagged, let's find all product links and their container
  const links = Array.from(document.querySelectorAll('a[href*="/p/"]'));
  const processed = [];
  const seenHrefs = new Set();

  for (const a of links) {
    const href = a.href.split('?')[0];
    if (seenHrefs.has(href)) continue;
    seenHrefs.add(href);

    // Find the enclosing card container
    let card = a;
    while (card && card.tagName !== 'LI' && !card.getAttribute('data-automation-id')?.includes('product') && card !== document.body) {
      card = card.parentElement;
    }

    const titleEl = card.querySelector('h2, h3, a[title], [class*="productTitle"], [class*="title"]') || a;
    const priceEl = card.querySelector('[data-automation-id*="price"], [class*="price"], [class*="Price"]');
    const ratingEl = card.querySelector('[data-automation-id*="rating"], [class*="rating"], [class*="Rating"], [aria-label*="star"], [aria-label*="rating"]');

    processed.push({
      title: titleEl?.textContent?.trim() || a.textContent?.trim(),
      href: a.href,
      fullText: card.textContent?.trim().replace(/\s+/g, ' '),
      priceText: priceEl?.textContent?.trim(),
      ratingAria: ratingEl?.getAttribute('aria-label') || ratingEl?.textContent?.trim()
    });
  }
  return processed;
});

