// Find all cards with price under 20
const results = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/p/"]'));
  const found = [];
  const seen = new Set();

  for (const a of links) {
    const href = a.href;
    if (seen.has(href)) continue;
    seen.add(href);

    let card = a;
    while (card && card.tagName !== 'LI' && !card.getAttribute('data-automation-id')?.includes('product') && card !== document.body) {
      card = card.parentElement;
    }

    const text = card ? card.textContent.replace(/\s+/g, ' ') : '';
    // Look for price patterns
    // e.g. $8.39, $17.60, etc.
    const priceMatch = text.match(/\$(\d+(\.\d{2})?)/g);
    if (priceMatch) {
      const prices = priceMatch.map(p => parseFloat(p.replace('$', '')));
      const minPrice = Math.min(...prices);
      if (minPrice < 20) {
        found.push({
          name: a.getAttribute('title') || a.textContent.trim() || card.querySelector('h2, h3')?.textContent.trim(),
          href,
          minPrice,
          allPrices: priceMatch,
          fullText: text
        });
      }
    }
  }
  return found;
});

console.log("Filtered products under $20:", JSON.stringify(results, null, 2));

